CREATE TABLE "User" (
                        "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                        "name" varchar NOT NULL,
                        "username" varchar UNIQUE NOT NULL,
                        "email" varchar UNIQUE NOT NULL,
                        "phone" varchar NOT NULL DEFAULT '',
                        "has_avatar" bool NOT NULL DEFAULT false,
                        "password" varchar NOT NULL,
                        "salt" varchar NOT NULL,
                        "email_verified" bool NOT NULL DEFAULT false,
                        "phone_verified" bool NOT NULL DEFAULT false,
                        "two_factor_enabled" bool NOT NULL DEFAULT false,
                        "two_factor_secret" varchar,
                        "last_login" timestamp,
                        "login_attempts" integer NOT NULL DEFAULT 0,
                        "locked_until" timestamp,
                        "password_changed_at" timestamp NOT NULL,
                        "role_id" integer NOT NULL,
                        "is_superuser" bool NOT NULL DEFAULT false,
                        "status_id" integer NOT NULL,
                        "deleted_at" timestamp,
                        "created_at" timestamp NOT NULL DEFAULT (now()),
                        "updated_at" timestamp NOT NULL DEFAULT (now())
);

CREATE TABLE "Role" (
                        "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                        "name" varchar UNIQUE NOT NULL
);

CREATE TABLE "UserStatus" (
                              "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                              "name" varchar UNIQUE NOT NULL
);

CREATE TABLE "Item" (
                        "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                        "name" varchar NOT NULL,
                        "category_id" integer NOT NULL,
                        "description" text,
                        "quantity" text,
                        "has_image" bool NOT NULL DEFAULT false,
                        "is_deleted" bool NOT NULL DEFAULT false,
                        "stored_at" timestamp NOT NULL DEFAULT (now()),
                        "updated_at" timestamp NOT NULL DEFAULT (now()),
                        "expires_at" timestamp NOT NULL,
                        "storage_id" integer NOT NULL,
                        "shelf" integer,
                        "last_modified" integer NOT NULL
);

CREATE TABLE "Category" (
                            "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                            "name" varchar NOT NULL
);

CREATE TABLE "Storage" (
                           "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                           "name" varchar NOT NULL,
                           "description" text,
                           "location" varchar,
                           "shelves" integer,
                           "has_image" bool NOT NULL DEFAULT false,
                           "owner" integer NOT NULL
);

CREATE TABLE "Announcement" (
                                "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                                "name" varchar NOT NULL,
                                "description" text,
                                "external_link" text,
                                "hasRead" bool NOT NULL DEFAULT false
);

CREATE TABLE "ShoppingListItem" (
                                    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                                    "name" varchar NOT NULL,
                                    "description" text,
                                    "quantity" text,
                                    "isChecked" bool NOT NULL DEFAULT false,
                                    "isDeleted" bool NOT NULL DEFAULT false,
                                    "created_at" timestamp NOT NULL DEFAULT (now()),
                                    "updated_at" timestamp NOT NULL DEFAULT (now()),
                                    "last_modified" integer NOT NULL
);

CREATE TABLE "Share" (
                         "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                         "source_user_id" integer NOT NULL,
                         "storage_id" integer NOT NULL,
                         "target_user_id" integer NOT NULL,
                         "can_share" bool NOT NULL DEFAULT false,
                         "shared_at" timestamp NOT NULL DEFAULT (now())
);

CREATE TABLE "Languages" (
                             "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                             "en" text NOT NULL,
                             "hu" text NOT NULL,
                             "ro" text NOT NULL,
                             "es" text NOT NULL,
                             "zh" text NOT NULL,
                             "fr" text NOT NULL,
                             "de" text NOT NULL,
                             "pt" text NOT NULL,
                             "ru" text NOT NULL,
                             "ua" text NOT NULL,
                             "ar" text NOT NULL
);

CREATE TABLE "Log" (
                       "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                       "created_at" timestamp NOT NULL DEFAULT (now()),
                       "action_type" integer NOT NULL,
                       "message" text,
                       "data" text,
                       "user_id" integer NOT NULL
);

CREATE TABLE "ActionType" (
                              "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                              "name" varchar UNIQUE NOT NULL
);

ALTER TABLE "User" ADD FOREIGN KEY ("role_id") REFERENCES "Role" ("id");

ALTER TABLE "User" ADD FOREIGN KEY ("status_id") REFERENCES "UserStatus" ("id");

ALTER TABLE "Item" ADD FOREIGN KEY ("category_id") REFERENCES "Category" ("id");

ALTER TABLE "Item" ADD FOREIGN KEY ("storage_id") REFERENCES "Storage" ("id");

ALTER TABLE "Item" ADD FOREIGN KEY ("last_modified") REFERENCES "User" ("id");

ALTER TABLE "Storage" ADD FOREIGN KEY ("owner") REFERENCES "User" ("id");

ALTER TABLE "ShoppingListItem" ADD FOREIGN KEY ("last_modified") REFERENCES "User" ("id");

ALTER TABLE "Share" ADD FOREIGN KEY ("source_user_id") REFERENCES "User" ("id");

ALTER TABLE "Share" ADD FOREIGN KEY ("storage_id") REFERENCES "Storage" ("id");

ALTER TABLE "Share" ADD FOREIGN KEY ("target_user_id") REFERENCES "User" ("id");

ALTER TABLE "Log" ADD FOREIGN KEY ("action_type") REFERENCES "ActionType" ("id");

ALTER TABLE "Log" ADD FOREIGN KEY ("user_id") REFERENCES "User" ("id");
